const S3_ENDPOINT = "https://s3.us.archive.org";
const METADATA_ENDPOINT = "https://archive.org/metadata";
const DOWNLOAD_ENDPOINT = "https://archive.org/download";

function getMimeType(e) {
  const t = (e.split(".").pop() || "").toLowerCase();
  return {
    jpg: "image/jpeg",
    jpeg: "image/jpeg",
    png: "image/png",
    webp: "image/webp",
    gif: "image/gif",
    svg: "image/svg+xml",
    mp4: "video/mp4",
    webm: "video/webm",
    mkv: "video/x-matroska",
    mp3: "audio/mpeg",
    ass: "text/plain",
    srt: "text/plain",
    vtt: "text/vtt",
    json: "application/json",
    xml: "application/xml",
    pdf: "application/pdf",
    txt: "text/plain"
  }[t] || "application/octet-stream";
}

function getCredentials(request, env) {
  const hA = request.headers.get("x-ia-access-key");
  const hS = request.headers.get("x-ia-secret-key");
  const accessKey = (hA || env.IA_ACCESS_KEY || "").trim();
  const secretKey = (hS || env.IA_SECRET_KEY || "").trim();
  return { accessKey, secretKey };
}

function getAuthHeader(accessKey, secretKey) {
  if (!accessKey || !secretKey) return null;
  return "LOW " + accessKey + ":" + secretKey;
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (request.method === "OPTIONS") {
      return new Response(null, {
        headers: {
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "GET, POST, PUT, DELETE, OPTIONS",
          "Access-Control-Allow-Headers": "Content-Type, Authorization, x-ia-access-key, x-ia-secret-key"
        }
      });
    }

    try {
      if (url.pathname.startsWith("/api/")) {
        return handleApiRequest(request, env, ctx, url);
      }
      return new Response(DASHBOARD_HTML, {
        headers: {
          "Content-Type": "text/html; charset=utf-8",
          "Cache-Control": "no-cache"
        }
      });
    } catch (err) {
      return new Response(JSON.stringify({ ok: false, error: err.message || "Internal server error" }), {
        status: 500,
        headers: {
          "Content-Type": "application/json",
          "Access-Control-Allow-Origin": "*"
        }
      });
    }
  }
};

async function handleApiRequest(request, env, ctx, url) {
  const jsonHeaders = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*"
  };

  const { accessKey, secretKey } = getCredentials(request, env);
  const defaultItem = (env.DEFAULT_ITEM || "").trim();

  if (url.pathname === "/api/s3-status") {
    const configured = Boolean(accessKey && secretKey);
    return new Response(JSON.stringify({
      connected: configured,
      configured: configured,
      source: "environment",
      defaultItem: defaultItem
    }), { headers: jsonHeaders });
  }

  if (url.pathname === "/api/buckets" && request.method === "GET") {
    if (!accessKey || !secretKey) {
      return new Response(JSON.stringify({ ok: false, error: "Cloudflare secret IA_ACCESS_KEY or IA_SECRET_KEY missing", buckets: [] }), { status: 401, headers: jsonHeaders });
    }
    try {
      const s3Res = await fetch(S3_ENDPOINT + "/", {
        headers: { "Authorization": getAuthHeader(accessKey, secretKey) }
      });
      if (!s3Res.ok) {
        return new Response(JSON.stringify({ ok: false, error: "S3 Buckets listing failed: " + s3Res.status, buckets: [] }), { status: s3Res.status, headers: jsonHeaders });
      }
      const xml = await s3Res.text();
      const buckets = [];
      const regex = /<Bucket>[\s\S]*?<Name>([^<]+)<\/Name>/gi;
      let match;
      while ((match = regex.exec(xml)) !== null) {
        if (match[1]) buckets.push(match[1].trim());
      }
      return new Response(JSON.stringify({ ok: true, buckets: buckets }), { headers: jsonHeaders });
    } catch (e) {
      return new Response(JSON.stringify({ ok: false, error: e.message, buckets: [] }), { status: 500, headers: jsonHeaders });
    }
  }

  if (url.pathname === "/api/files" && request.method === "GET") {
    const item = (url.searchParams.get("item") || defaultItem || "").trim();
    if (!item) {
      return new Response(JSON.stringify({ ok: false, error: "Item identifier is required" }), { status: 400, headers: jsonHeaders });
    }
    const metaRes = await fetch(METADATA_ENDPOINT + "/" + encodeURIComponent(item) + "/files?t=" + Date.now());
    if (!metaRes.ok) {
      return new Response(JSON.stringify({ ok: false, error: "Metadata API error: " + metaRes.status }), { status: metaRes.status, headers: jsonHeaders });
    }
    const data = await metaRes.json();
    const rawFiles = data.result || [];
    let totalBytes = 0;
    const files = rawFiles.map(r => {
      const size = parseInt(r.size || "0", 10) || 0;
      totalBytes += size;
      return {
        name: r.name,
        size: size,
        format: r.format || (r.name.split(".").pop() || "").toUpperCase(),
        mtime: r.mtime ? parseInt(r.mtime, 10) * 1000 : null,
        source: r.source || "unknown",
        md5: r.md5 || ""
      };
    });
    return new Response(JSON.stringify({
      ok: true,
      files: files,
      totalFiles: files.length,
      totalBytes: totalBytes
    }), { headers: jsonHeaders });
  }

  if (url.pathname === "/api/views" && request.method === "GET") {
    const item = (url.searchParams.get("item") || defaultItem || "").trim();
    if (!item) {
      return new Response(JSON.stringify({ ok: false, views: null }), { headers: jsonHeaders });
    }
    try {
      const viewsRes = await fetch("https://be-api.us.archive.org/views/v1/short/" + encodeURIComponent(item));
      if (viewsRes.ok) {
        const vData = await viewsRes.json();
        return new Response(JSON.stringify({ ok: true, views: vData[item] || null }), { headers: jsonHeaders });
      }
    } catch {}
    return new Response(JSON.stringify({ ok: false, views: null }), { headers: jsonHeaders });
  }

  if (url.pathname === "/api/ia-tasks" && request.method === "GET") {
    const item = (url.searchParams.get("item") || defaultItem || "").trim();
    if (!item) {
      return new Response(JSON.stringify({ ok: false, tasks: [], is_pending: false }), { headers: jsonHeaders });
    }
    try {
      const tRes = await fetch(METADATA_ENDPOINT + "/" + encodeURIComponent(item) + "?t=" + Date.now());
      if (tRes.ok) {
        const data = await tRes.json();
        return new Response(JSON.stringify({
          ok: true,
          tasks: data.tasks || [],
          is_pending: !!data.is_pending
        }), { headers: jsonHeaders });
      }
    } catch {}
    return new Response(JSON.stringify({ ok: false, tasks: [], is_pending: false }), { headers: jsonHeaders });
  }

  if (url.pathname === "/api/upload" && (request.method === "PUT" || request.method === "POST")) {
    if (!accessKey || !secretKey) {
      return new Response(JSON.stringify({ ok: false, error: "Cloudflare secret IA_ACCESS_KEY or IA_SECRET_KEY missing" }), { status: 401, headers: jsonHeaders });
    }
    const item = (url.searchParams.get("item") || defaultItem || "").trim();
    let filePath = (url.searchParams.get("path") || "").trim().replace(/^\/+/g, "");
    if (!item || !filePath) {
      return new Response(JSON.stringify({ ok: false, error: "item and path are required" }), { status: 400, headers: jsonHeaders });
    }
    const s3Url = S3_ENDPOINT + "/" + encodeURIComponent(item) + "/" + encodeURI(filePath);
    const contentType = request.headers.get("content-type") || getMimeType(filePath);
    const bodyData = await request.arrayBuffer();

    const s3Res = await fetch(s3Url, {
      method: "PUT",
      headers: {
        "Authorization": getAuthHeader(accessKey, secretKey),
        "Content-Type": contentType,
        "x-archive-keep-old-version": "0",
        "x-archive-queue-derive": "1"
      },
      body: bodyData
    });

    if (!s3Res.ok) {
      const errText = await s3Res.text();
      return new Response(JSON.stringify({ ok: false, error: "S3 Upload failed (" + s3Res.status + "): " + errText }), { status: s3Res.status, headers: jsonHeaders });
    }

    return new Response(JSON.stringify({ ok: true, item, path: filePath }), { headers: jsonHeaders });
  }

  if (url.pathname === "/api/delete" && request.method === "POST") {
    if (!accessKey || !secretKey) {
      return new Response(JSON.stringify({ ok: false, error: "Cloudflare secret IA_ACCESS_KEY or IA_SECRET_KEY missing" }), { status: 401, headers: jsonHeaders });
    }
    const payload = await request.json().catch(() => ({}));
    const item = (payload.item || url.searchParams.get("item") || defaultItem || "").trim();
    const filePath = (payload.path || url.searchParams.get("path") || "").trim().replace(/^\/+/g, "");
    const cascade = payload.cascade !== false;
    if (!item || !filePath) {
      return new Response(JSON.stringify({ ok: false, error: "item and path are required" }), { status: 400, headers: jsonHeaders });
    }

    const s3Url = S3_ENDPOINT + "/" + encodeURIComponent(item) + "/" + encodeURI(filePath);
    const headers = { "Authorization": getAuthHeader(accessKey, secretKey) };
    if (cascade) headers["x-archive-cascade-delete"] = "1";

    const s3Res = await fetch(s3Url, { method: "DELETE", headers: headers });
    if (!s3Res.ok && s3Res.status !== 204 && s3Res.status !== 200) {
      const errText = await s3Res.text();
      return new Response(JSON.stringify({ ok: false, error: "S3 Delete failed (" + s3Res.status + "): " + errText }), { status: s3Res.status, headers: jsonHeaders });
    }

    return new Response(JSON.stringify({ ok: true, item, path: filePath }), { headers: jsonHeaders });
  }

  if (url.pathname === "/api/move" && request.method === "POST") {
    if (!accessKey || !secretKey) {
      return new Response(JSON.stringify({ ok: false, error: "Cloudflare secret IA_ACCESS_KEY or IA_SECRET_KEY missing" }), { status: 401, headers: jsonHeaders });
    }
    const payload = await request.json().catch(() => ({}));
    const item = (payload.item || defaultItem || "").trim();
    let oldPath = (payload.oldPath || "").trim().replace(/^\/+/g, "");
    let newPath = (payload.newPath || "").trim().replace(/^\/+/g, "");
    if (!item || !oldPath || !newPath) {
      return new Response(JSON.stringify({ ok: false, error: "item, oldPath, and newPath are required" }), { status: 400, headers: jsonHeaders });
    }

    const destS3Url = S3_ENDPOINT + "/" + encodeURIComponent(item) + "/" + encodeURI(newPath);
    let copySuccess = false;
    try {
      const copyRes = await fetch(destS3Url, {
        method: "PUT",
        headers: {
          "Authorization": getAuthHeader(accessKey, secretKey),
          "x-amz-copy-source": "/" + encodeURIComponent(item) + "/" + encodeURI(oldPath),
          "x-archive-keep-old-version": "0"
        }
      });
      if (copyRes.ok) copySuccess = true;
    } catch {}

    if (!copySuccess) {
      const dlUrl = DOWNLOAD_ENDPOINT + "/" + encodeURIComponent(item) + "/" + encodeURI(oldPath);
      const dlRes = await fetch(dlUrl);
      if (!dlRes.ok) {
        return new Response(JSON.stringify({ ok: false, error: "Failed to download source file for moving" }), { status: dlRes.status, headers: jsonHeaders });
      }
      const data = await dlRes.arrayBuffer();
      const putRes = await fetch(destS3Url, {
        method: "PUT",
        headers: {
          "Authorization": getAuthHeader(accessKey, secretKey),
          "Content-Type": getMimeType(newPath),
          "x-archive-keep-old-version": "0",
          "x-archive-queue-derive": "1"
        },
        body: data
      });
      if (!putRes.ok) {
        const errText = await putRes.text();
        return new Response(JSON.stringify({ ok: false, error: "Copy PUT failed (" + putRes.status + "): " + errText }), { status: putRes.status, headers: jsonHeaders });
      }
    }

    const srcS3Url = S3_ENDPOINT + "/" + encodeURIComponent(item) + "/" + encodeURI(oldPath);
    await fetch(srcS3Url, {
      method: "DELETE",
      headers: { "Authorization": getAuthHeader(accessKey, secretKey) }
    });

    return new Response(JSON.stringify({ ok: true, item, oldPath, newPath }), { headers: jsonHeaders });
  }

  return new Response(JSON.stringify({ ok: false, error: "Endpoint not found" }), { status: 404, headers: jsonHeaders });
}

